package com.tr069.client.data.network

/**
 * Production-ready VirtualParameter scripts for GenieACS server auto-provisioning.
 * Supports all major ONU vendors: ZTE, Huawei, Fiberhome, VSOL, C-Data, Nokia, XPON, etc.
 */
object VirtualParamTemplates {
    val STANDARD_TEMPLATES: Map<String, String> = mapOf(
        "RXPower" to "// ALIJAYA NET - Universal Multi-Vendor RXPower\nlet m = \"N/A\";\nlet paths = [\n  // ZTE & OEM\n  \"InternetGatewayDevice.WANDevice.*.X_ZTE-COM_WANPONInterfaceConfig.RXPower\",\n  \"InternetGatewayDevice.WANDevice.*.X_CMCC_EponInterfaceConfig.RXPower\",\n  \"InternetGatewayDevice.WANDevice.*.X_CMCC_GponInterfaceConfig.RXPower\",\n  \"InternetGatewayDevice.WANDevice.*.X_CU_WANEPONInterfaceConfig.OpticalTransceiver.RXPower\",\n  // Huawei\n  \"InternetGatewayDevice.WANDevice.*.X_GponInterafceConfig.RXPower\",\n  \"InternetGatewayDevice.WANDevice.*.X_GponInterfaceConfig.RXPower\",\n  // FiberHome\n  \"InternetGatewayDevice.WANDevice.*.X_FH_GponInterfaceConfig.RXPower\",\n  \"InternetGatewayDevice.WANDevice.*.X_FH_EponInterfaceConfig.RXPower\",\n  // Nokia / Alcatel-Lucent\n  \"InternetGatewayDevice.WANDevice.*.X_ALU_COM_GponInterfaceConfig.RXPower\",\n  \"InternetGatewayDevice.WANDevice.*.X_ALU-COM_GponInterfaceConfig.RXPower\",\n  \"InternetGatewayDevice.WANDevice.*.X_NOKIA_GponInterfaceConfig.RXPower\",\n  \"Device.Optical.Interface.1.RXPower\",\n  // Raiscom\n  \"InternetGatewayDevice.WANDevice.*.X_RAISCOM_GponInterfaceConfig.RXPower\",\n  \"InternetGatewayDevice.WANDevice.*.X_RAISCOM_EponInterfaceConfig.RXPower\",\n  // BDCOM\n  \"InternetGatewayDevice.WANDevice.*.X_BDCOM_GponInterfaceConfig.RXPower\",\n  \"InternetGatewayDevice.WANDevice.*.X_BDCOM_EponInterfaceConfig.RXPower\",\n  // CIOT / VSOL / C-Data / HSGQ / BDCOM / CT-COM standard\n  \"InternetGatewayDevice.WANDevice.*.X_CT-COM_GponInterfaceConfig.RXPower\",\n  \"InternetGatewayDevice.WANDevice.*.X_CT-COM_EponInterfaceConfig.RXPower\",\n  \"InternetGatewayDevice.WANDevice.*.X_VSOL_GponInterfaceConfig.RXPower\",\n  \"InternetGatewayDevice.WANDevice.*.X_CDATA_GponInterfaceConfig.RXPower\",\n  // Generic standard TR-098\n  \"InternetGatewayDevice.WANDevice.*.WANCommonInterfaceConfig.OpticalPower\"\n];\n\nfor (let i = 0; i < paths.length; i++) {\n  let d = declare(paths[i], {value: 1});\n  for (let p of d) {\n    if (p.value && p.value[0] !== undefined && p.value[0] !== null && p.value[0] !== \"\") {\n      let raw = parseFloat(p.value[0]);\n      if (isNaN(raw)) continue;\n\n      if (raw < 0 && raw > -50) {\n        m = raw.toFixed(2);\n      } else if (raw <= -50) {\n        m = (raw / 100).toFixed(2);\n      } else if (raw > 0) {\n        let dbm = 30 + (Math.log10(raw * 1e-7) * 10);\n        m = (Math.round(dbm * 100) / 100).toFixed(2);\n      }\n      if (m !== \"N/A\") break;\n    }\n  }\n  if (m !== \"N/A\") break;\n}\n\nreturn {writable: false, value: [m, \"xsd:string\"]};\n",
        "pppoeUsername" to "// ALIJAYA NET - Universal 2-Way Writable PPPoE Username\nlet username = \"N/A\";\nconst now = Date.now();\n\nif (args[1] && args[1].value) {\n  username = String(args[1].value[0]).trim();\n  declare(\"InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.Username\", null, {value: username});\n} else {\n  let paths = [\n    \"InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.Username\",\n    \"Device.PPP.Interface.*.Username\"\n  ];\n  for (let i = 0; i < paths.length; i++) {\n    let d = declare(paths[i], {value: now - 300000});\n    for (let p of d) {\n      if (p.value && p.value[0] !== undefined && p.value[0] !== null && p.value[0] !== \"\") {\n        let val = String(p.value[0]).trim();\n        if (val !== \"\") {\n          username = val;\n          break;\n        }\n      }\n    }\n    if (username !== \"N/A\") break;\n  }\n}\n\nreturn {writable: true, value: [username, \"xsd:string\"]};\n",
        "WlanPassword" to "// ALIJAYA NET - Universal Multi-Vendor WiFi Password (TR-098 & TR-181)\nlet m = \"\";\nif (args[1] && args[1].value) {\n  m = String(args[1].value[0]).trim();\n  declare(\"InternetGatewayDevice.LANDevice.1.WLANConfiguration.1.KeyPassphrase\", null, {value: m});\n  declare(\"InternetGatewayDevice.LANDevice.1.WLANConfiguration.1.PreSharedKey.1.KeyPassphrase\", null, {value: m});\n  declare(\"InternetGatewayDevice.LANDevice.*.WLANConfiguration.*.KeyPassphrase\", null, {value: m});\n  declare(\"InternetGatewayDevice.LANDevice.*.WLANConfiguration.*.PreSharedKey.1.KeyPassphrase\", null, {value: m});\n  declare(\"Device.WiFi.AccessPoint.1.Security.KeyPassphrase\", null, {value: m});\n  declare(\"Device.WiFi.AccessPoint.*.Security.KeyPassphrase\", null, {value: m});\n  return {writable: true, value: [m, \"xsd:string\"]};\n}\n\nlet paths = [\n  \"InternetGatewayDevice.LANDevice.1.WLANConfiguration.1.KeyPassphrase\",\n  \"InternetGatewayDevice.LANDevice.1.WLANConfiguration.1.PreSharedKey.1.KeyPassphrase\",\n  \"InternetGatewayDevice.LANDevice.*.WLANConfiguration.*.KeyPassphrase\",\n  \"InternetGatewayDevice.LANDevice.*.WLANConfiguration.*.PreSharedKey.1.KeyPassphrase\",\n  \"InternetGatewayDevice.LANDevice.*.WLANConfiguration.*.X_HW_KeyPassphrase\",\n  \"InternetGatewayDevice.LANDevice.*.WLANConfiguration.*.X_CMCC_KeyPassphrase\",\n  \"Device.WiFi.AccessPoint.1.Security.KeyPassphrase\",\n  \"Device.WiFi.AccessPoint.*.Security.KeyPassphrase\"\n];\n\nfor (let i = 0; i < paths.length; i++) {\n  let d = declare(paths[i], {value: 1});\n  for (let item of d) {\n    if (item.value && item.value[0] !== undefined && item.value[0] !== null) {\n      let val = String(item.value[0]).trim();\n      if (val !== \"\") {\n        m = val;\n        break;\n      }\n    }\n  }\n  if (m !== \"\") break;\n}\n\nreturn {writable: true, value: [m, \"xsd:string\"]};",
        "WlanSSID" to "// ALIJAYA NET - Universal WiFi SSID\nif (args[1].value) {\n  let val = args[1].value[0];\n  declare(\"InternetGatewayDevice.LANDevice.1.WLANConfiguration.1.SSID\", null, {value: val});\n  declare(\"InternetGatewayDevice.LANDevice.*.WLANConfiguration.1.SSID\", null, {value: val});\n  return {writable: true, value: [val, \"xsd:string\"]};\n}\n\nlet ssid = \"\";\nlet paths = [\n  \"InternetGatewayDevice.LANDevice.1.WLANConfiguration.1.SSID\",\n  \"InternetGatewayDevice.LANDevice.*.WLANConfiguration.1.SSID\",\n  \"Device.WiFi.SSID.1.SSID\"\n];\n\nfor (let p of paths) {\n  let d = declare(p, {value: 1});\n  for (let item of d) {\n    if (item.value && item.value[0] && typeof item.value[0] === 'string') {\n      let val = item.value[0];\n      if (val !== \"\") {\n        ssid = val;\n        break;\n      }\n    }\n  }\n  if (ssid !== \"\") break;\n}\n\nreturn {writable: true, value: [ssid, \"xsd:string\"]};",
        "getponmode" to "// ALIJAYA NET - PON Mode\nlet pon = \"\";\nlet v1 = declare(\"InternetGatewayDevice.WANDevice.*.WANCommonInterfaceConfig.WANAccessType\", {value: 1});\nif (v1 && v1.size && v1.value && v1.value[0]) {\n  pon = String(v1.value[0]).toUpperCase();\n}\n\nif (!pon) {\n  let eponCheck = declare(\"InternetGatewayDevice.WANDevice.*.X_CT-COM_EponInterfaceConfig.RXPower\", {value: 1});\n  if (eponCheck && eponCheck.size) {\n    pon = \"EPON\";\n  } else {\n    let gponCheck = declare(\"InternetGatewayDevice.WANDevice.*.X_CT-COM_GponInterfaceConfig.RXPower\", {value: 1});\n    if (gponCheck && gponCheck.size) {\n      pon = \"GPON\";\n    }\n  }\n}\n\nif (pon.includes(\"EPON\")) {\n  pon = \"EPON\";\n} else if (pon.includes(\"GPON\") || pon.includes(\"PON\")) {\n  pon = \"GPON\";\n} else {\n  pon = \"Ethernet\";\n}\n\nreturn {writable: false, value: [pon, \"xsd:string\"]};",
        "MacAddress" to "// ALIJAYA NET - Universal MAC Address\nlet mac = \"\";\nlet paths = [\n  \"InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.MACAddress\",\n  \"InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANIPConnection.*.MACAddress\",\n  \"InternetGatewayDevice.LANDevice.1.LANHostConfigManagement.MACAddress\",\n  \"InternetGatewayDevice.DeviceInfo.X_CU_SerialNumber\",\n  \"Device.PPP.Interface.*.MACAddress\"\n];\n\nfor (let i = 0; i < paths.length; i++) {\n  let d = declare(paths[i], {value: 1});\n  for (let p of d) {\n    if (p.value && p.value[0] && typeof p.value[0] === 'string') {\n      let val = p.value[0].trim();\n      if (val !== \"\" && val !== \"00:00:00:00:00:00\" && val.includes(\":\")) {\n        mac = val;\n        break;\n      }\n    }\n  }\n  if (mac !== \"\") break;\n}\n\nreturn {writable: false, value: [mac || \"Ethernet\", \"xsd:string\"]};",
        "userconnected" to "// Total active all ssid\nlet active = 0;\nlet isNumber = (value) => {\n  return typeof value === \"number\" && isFinite(value);\n};\n\nlet ssid1 = declare(\"InternetGatewayDevice.LANDevice.1.WLANConfiguration.1.TotalAssociations\", {value: 1});\n\nif (ssid1 && ssid1.size && isNumber(ssid1.value[0])) {\n  active += ssid1.value[0];\n}\n\nreturn {writable: false, value: [String(active), \"xsd:unsignedInt\"]};\n",
        "uptimeDevice" to "// ALIJAYA NET - Universal PPPoE Uptime\nlet totalSecs = 0;\nlet paths = [\n  \"InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.Uptime\",\n  \"InternetGatewayDevice.DeviceInfo.UpTime\",\n  \"Device.DeviceInfo.UpTime\"\n];\n\nfor (let i = 0; i < paths.length; i++) {\n  let d = declare(paths[i], {value: 1});\n  for (let p of d) {\n    if (p.value && p.value[0] !== undefined) {\n      let s = parseInt(p.value[0], 10);\n      if (!isNaN(s) && s > 0) {\n        totalSecs = s;\n        break;\n      }\n    }\n  }\n  if (totalSecs > 0) break;\n}\n\nif (totalSecs <= 0) {\n  return {writable: false, value: [\"0d 00:00:00\", \"xsd:string\"]};\n}\n\nlet days = Math.floor(totalSecs / 86400);\nlet rem  = totalSecs % 86400;\nlet hrs  = Math.floor(rem / 3600);\nlet mins = Math.floor((rem % 3600) / 60);\nlet secs = rem % 60;\n\nlet pad = (n) => (n < 10 ? \"0\" + n : \"\" + n);\nlet uptime = days + \"d \" + pad(hrs) + \":\" + pad(mins) + \":\" + pad(secs);\n\nreturn {writable: false, value: [uptime, \"xsd:string\"]};",
        "vlan" to "// ALIJAYA NET - Universal 2-Way Writable Multi-Vendor VLAN ID\nlet vlan = \"\";\nconst now = Date.now();\n\n// 1. Write mode: User edits VLAN in GenieACS Web UI\nif (args[1] && args[1].value) {\n  vlan = String(args[1].value[0]).trim();\n  const brandDecl = declare(\"DeviceID.Manufacturer\", {value: 1});\n  const brand = (brandDecl && brandDecl.value && brandDecl.value[0]) ? String(brandDecl.value[0]).toUpperCase() : \"\";\n\n  if (brand.includes(\"HUAWEI\")) {\n    declare(\"InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.X_HW_VLAN\", null, {value: vlan});\n  } else if (brand.includes(\"ZTE\") || brand.includes(\"ZICG\")) {\n    declare(\"InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.X_CMCC_VLANIDMark\", null, {value: vlan});\n    declare(\"InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.X_CMCC_VLANMode\", null, {value: 1});\n    declare(\"InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.X_ZTE-COM_VlanID\", null, {value: vlan});\n    declare(\"InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.VLANID\", null, {value: vlan});\n  } else if (brand.includes(\"NOKIA\") || brand.includes(\"ALCATEL\")) {\n    declare(\"InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.X_ALU_COM_VlanID\", null, {value: vlan});\n    declare(\"InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.VLANID\", null, {value: vlan});\n  } else if (brand.includes(\"CIOT\") || brand.includes(\"FIBERHOME\") || brand.includes(\"RTEG\") || brand.includes(\"RAISCOM\")) {\n    declare(\"InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.X_CT-COM_VlanID\", null, {value: vlan});\n    declare(\"InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.X_CT-COM_Mode\", null, {value: 1});\n    declare(\"InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.VLANID\", null, {value: vlan});\n  } else {\n    declare(\"InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.VLANID\", null, {value: vlan});\n    declare(\"InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.VLANID\", null, {value: vlan});\n    declare(\"InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.X_CT-COM_VlanID\", null, {value: vlan});\n    declare(\"InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.X_CMCC_VLANIDMark\", null, {value: vlan});\n    declare(\"InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.X_HW_VLAN\", null, {value: vlan});\n  }\n}\n// 2. Read mode\nelse {\n  const paths = [\n    \"InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.X_HW_VLAN\",\n    \"InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.X_CT-COM_VlanID\",\n    \"InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.X_CMCC_VLANIDMark\",\n    \"InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.X_ZTE-COM_VlanID\",\n    \"InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.X_ALU_COM_VlanID\",\n    \"InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.VLANID\",\n    \"InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.VLANID\",\n    \"InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANPPPConnection.*.X_BROADCOM_COM_VLANID\",\n    \"InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.WANEponInterfaceConfig.VLANID\",\n    \"InternetGatewayDevice.WANDevice.*.WANConnectionDevice.*.X_CT-COM_WANGponLinkConfig.VLANIDMark\"\n  ];\n\n  for (let i = 0; i < paths.length; i++) {\n    const d = declare(paths[i], {value: now - 300000});\n    for (let p of d) {\n      if (p.value && p.value[0] !== undefined && p.value[0] !== null && p.value[0] !== \"\") {\n        const val = String(p.value[0]).trim();\n        if (val !== \"\" && val !== \"0\" && val !== \"undefined\" && val !== \"null\") {\n          vlan = val;\n          break;\n        }\n      }\n    }\n    if (vlan !== \"\") break;\n  }\n}\n\nreturn {writable: true, value: [vlan || \"-\", \"xsd:string\"]};\n",
    )
}
